package vn.rtr.aeris.integration03;
import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;
/** Bounded diagnostic ring. No per-event storage and no flight/authority effects. */
public final class StageTrace03{
 private final File root;private String id=null;private final List<Object>events=new ArrayList<>();private final Map<String,Long>counts=new LinkedHashMap<>();private int overflow=0,sampledOut=0;private long serial=0;
 public StageTrace03(File root){this.root=root;}
 public synchronized void begin(String name)throws Exception{if(id!=null||!name.matches("[a-f0-9-]{36}"))throw new IOException("TRACE03_CONTEXT");File[]old=root.listFiles();if(old!=null&&old.length>=32)throw new IOException("TRACE03_QUOTA_NO_DELETE");id=name;events.clear();counts.clear();overflow=0;sampledOut=0;serial=0;}
 public synchronized void mark(String stage,String key,long at){if(id==null)return;stage=stage==null?"UNKNOWN":stage.substring(0,Math.min(64,stage.length()));key=key==null?"":key.substring(0,Math.min(64,key.length()));if(!counts.containsKey(stage)&&counts.size()>=64){overflow++;return;}long count=counts.containsKey(stage)?counts.get(stage)+1:1;counts.put(stage,count);if((stage.startsWith("RX_")||stage.startsWith("DELIVERY_"))&&(count-1)%8!=0){sampledOut++;return;}if(events.size()>=512){overflow++;return;}events.add(Data97.m("n",++serial,"stage",stage.length()>64?stage.substring(0,64):stage,"key",key.length()>64?key.substring(0,64):key,"nativeElapsedMs",at,"thread",Thread.currentThread().getName()));}
 public String finish(String client)throws Exception{final String name;final List<Object>copy;final Map<String,Long>totals;final int lost,sampled; synchronized(this){if(id==null)throw new IOException("TRACE03_NOT_ACTIVE");name=id;id=null;copy=new ArrayList<>(events);totals=new LinkedHashMap<>(counts);lost=overflow;sampled=sampledOut;events.clear();counts.clear();}if(client==null||client.getBytes(StandardCharsets.UTF_8).length>49152)throw new IOException("TRACE03_CLIENT_BOUND");byte[]bytes=Data97.json(Data97.m("format","aeris-stage03-trace","version",1,"id",name,"clock","ANDROID_ELAPSED_REALTIME_MS","events",copy,"overflow",lost,"sampleEveryRx",8,"sampledOut",sampled,"stageCounts",totals,"retainedEventComplete",lost==0,"clientTraceJson",client,"provenance","DIAGNOSTIC_SAMPLED_NOT_EXECUTION_PROOF")).getBytes(StandardCharsets.UTF_8);if(bytes.length>196608)throw new IOException("TRACE03_TOTAL_BOUND");if(!root.isDirectory()&&!root.mkdirs())throw new IOException("TRACE03_DIR");if(root.getUsableSpace()<DraftStore.RESERVE+bytes.length)throw new IOException("TRACE03_RESERVE_NO_DELETE");File file=new File(root,name+".json");if(file.exists())throw new IOException("TRACE03_EXISTS");try(FileOutputStream out=new FileOutputStream(file)){out.write(bytes);out.getFD().sync();}return Data97.json(Data97.m("ok",true,"id",name,"sha256",DraftStore.hash(bytes),"bytes",bytes.length,"overflow",lost,"sampledOut",sampled));}
}
